PRAGMA foreign_keys=ON;
BEGIN;
-- ============================================================
-- RELATIONSHIP CONSISTENCY NORMALIZATION
-- ------------------------------------------------------------
-- Keep related records realistic beyond FK validity:
-- - A prescription ends after it starts.
-- - Billing appointments belong to the same patient.
-- - Billing insurance policies belong to the same patient.
-- ============================================================

UPDATE prescriptions
SET end_date = date(start_date, '+' || (3 + abs(random()) % 58) || ' days')
WHERE end_date IS NOT NULL;

UPDATE billing
SET appointment_id = (
    SELECT MIN(a.appointment_id)
    FROM appointments a
    WHERE a.patient_id = billing.patient_id
)
WHERE appointment_id IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM appointments a2
    WHERE a2.patient_id = billing.patient_id
  );

UPDATE billing
SET insurance_id = (
    SELECT MIN(i.insurance_id)
    FROM insurance i
    WHERE i.patient_id = billing.patient_id
)
WHERE insurance_id IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM insurance i2
    WHERE i2.patient_id = billing.patient_id
  );

COMMIT;
